(async()=>{
 const $=id=>document.getElementById(id),descriptions=['간결한 실루엣과 짧고 정확한 타격.','소재를 따라붙는 잔상과 선명한 접촉.','다층 잔상과 소재에서 갈라지는 파편.','기술명 등장, 깊어진 명암과 겹쳐지는 큰 타격.','기술명 등장, 폭넓은 다층 타격과 오래 남는 고유 파편.'];let manifest,selected='common',renderer,busy=false,frozen=false,sequence=0,slot=0,current=false;
 const arena=$('arena'),finisher=BattleFinisher.mount(arena),freeze=document.createElement('canvas');freeze.className='rarity-freeze-frame';freeze.hidden=true;arena.append(freeze);
 function clear(){frozen=false;freeze.hidden=true;}
 function select(rarity){sequence++;renderer?.cancel();finisher.cancel();busy=false;clear();selected=rarity;$('rarity-lab-finisher').disabled=rarity!=='mythic';for(const button of $('rarity-lab-tiers').children)button.setAttribute('aria-pressed',String(button.dataset.rarity===rarity));const profile=Craft.RarityEffects.profile(rarity),tier=manifest.tiers.find(t=>t.rarity===($('rarity-lab-shared').checked?'common':rarity));BattlePreview.weapon=Craft.normalizeCreative({...manifest.weapon,rarity,...(tier.meta?{effectAtlas:{id:tier.meta.id,layout:tier.meta.local.layout,readyRows:tier.meta.local.readyRows}}:{})});BattlePreview.weapon.artwork=manifest.image;$('rarity-lab-grade').textContent=profile.label;$('rarity-lab-skill').textContent=BattlePreview.weapon.moves[slot].name;$('rarity-lab-description').textContent=descriptions[profile.rank];$('rarity-lab-play').disabled=false;$('rarity-lab-freeze').disabled=true;}
 async function play(){if(busy||!manifest)return;const token=++sequence,finalBlow=$('rarity-lab-finisher').checked&&selected==='mythic';clear();finisher.cancel();busy=true;$('rarity-lab-play').disabled=true;$('rarity-lab-freeze').disabled=false;$('rarity-lab-status').textContent=Craft.Rarity.get(selected).label+' · '+BattlePreview.weapon.moves[slot].name;try{await renderer.play({...BattlePreview.weapon.moves[slot],atlasRow:slot},{},{feedback:{hit:BattlePreview.weapon.moves[slot].damage||0,heal:BattlePreview.weapon.moves[slot].heal||0}},{playbackRate:$('rarity-lab-slow').checked?.25:1,finisher:finalBlow,onContact:()=>{if(!finalBlow)return;return finisher.play(BattlePreview.weapon,{...BattlePreview.weapon.moves[slot],atlasRow:slot},{hit:Craft.Moves.forWeapon(BattlePreview.weapon)[slot].damage||0},{preview:true,playbackRate:$('rarity-lab-slow').checked?.25:1,onVisualFrame:frame=>{if($('rarity-lab-peak').checked&&frame.progress>=.3&&frame.progress<.85)freezeFrame(frame.canvas);}});},onVisualFrame:frame=>{if(!finalBlow&&$('rarity-lab-peak').checked&&frame.impactMs>=frame.impactDuration*.32&&frame.impactMs<frame.impactDuration)freezeFrame(frame.canvas);}});}catch(error){$('rarity-lab-status').textContent=error.message;}finally{if(token===sequence){busy=false;$('rarity-lab-play').disabled=false;$('rarity-lab-freeze').disabled=true;}}}
 function freezeFrame(canvas){if(!busy||frozen)return;freeze.width=canvas.width;freeze.height=canvas.height;freeze.getContext('2d').drawImage(canvas,0,0);freeze.hidden=false;frozen=true;renderer.cancel();finisher.freeze();$('rarity-lab-status').textContent='장면 정지 · 기술 사용을 누르면 다시 볼 수 있어';}
 $('rarity-lab-freeze').addEventListener('click',()=>freezeFrame(arena.querySelector('.battle-effect-canvas')));
 async function load(){try{const params=new URLSearchParams(location.hash.slice(1));if(params.has('build')||params.has('data')){const weapon=Craft.readBattleWeapon(location.hash);if(weapon.kind!=='custom'||!weapon.artwork||!weapon.moves?.every(m=>m.motionPlan))throw Error('이 무기는 전투 화면에서 직접 확인해 줘. 원본 기록은 그대로야.');current=true;manifest={weapon,image:weapon.artwork,tiers:Craft.RarityEffects.ids.map(rarity=>({rarity,meta:weapon.effectAtlas?{id:weapon.effectAtlas.id,local:weapon.effectAtlas}:null}))};$('rarity-lab-shared').checked=true;$('rarity-lab-shared').disabled=true;$('rarity-lab-note').textContent='지금 무기의 같은 도트로 재생 연출만 비교해. 저장된 무기의 등급·그림·기술은 바꾸지 않아.';}else{const response=await fetch('assets/studies/rarity-effects/manifest.json');if(!response.ok)throw Error('5등급 실제 도트를 생성하고 있어. 잠시 후 다시 확인해 줘.');manifest=await response.json();}for(const [i,move]of manifest.weapon.moves.entries()){if(!current&&i>0)break;const option=document.createElement('option');option.value=String(i);option.textContent=move.name;$('rarity-lab-move').append(option);}window.BattlePreview={weapon:{...manifest.weapon,artwork:manifest.image}};TrainerStudy.draw($('player-sprite'));await Craft.drawHeldArtwork($('held-battle-weapon'),manifest.image);Craft.attachToHand($('held-battle-weapon'),Craft.WeaponRig.normalize(manifest.weapon.rig,manifest.weapon));renderer=BattleMotion.mount(arena);for(const rarity of Craft.RarityEffects.ids){const button=document.createElement('button');button.type='button';button.dataset.rarity=rarity;button.textContent=Craft.Rarity.get(rarity).label;button.style.setProperty('--tier-color',GamePalette.tokens[Craft.Rarity.get(rarity).color]);button.addEventListener('click',()=>select(rarity));$('rarity-lab-tiers').append(button);}select(current&&Craft.Rarity.valid(manifest.weapon.rarity)?manifest.weapon.rarity:'common');$('rarity-lab-status').textContent='등급을 고르고 같은 기술을 비교해 봐.';$('rarity-lab-retry').hidden=true;}catch(error){$('rarity-lab-status').textContent=error.message;$('rarity-lab-retry').hidden=false;}}
 $('rarity-lab-play').addEventListener('click',play);$('rarity-lab-shared').addEventListener('change',()=>select(selected));$('rarity-lab-move').addEventListener('change',()=>{slot=Number($('rarity-lab-move').value);select(selected);});$('rarity-lab-retry').addEventListener('click',load);await load();
})();
